from pathlib import Path
import base64
import hashlib
import json
import shutil
import subprocess
import sys

# One-time integrity repair for the Batch E/F filename collision with frozen Pilot 02.
# This repair is independent of generated SHACL performance. It changes only synthetic
# Batch E/F case identifiers/file locations and restores the original Pilot-02 bytes.

PILOT_ORIGINALS_B64 = {'rdf/I2/I2-014/I2-014-F01.ttl': '', 'rdf/I2/I2-014/I2-014-F02.ttl': '', 'rdf/I2/I2-014/I2-014-F03.ttl': '', 'rdf/I2/I2-014/I2-014-F04.ttl': '', 'rdf/I2/I2-014/I2-014-F05.ttl': '', 'rdf/I2/I2-014/I2-014-P01.ttl': '', 'rdf/I2/I2-015/I2-015-F01.ttl': '', 'rdf/I2/I2-015/I2-015-F02.ttl': '', 'rdf/I2/I2-015/I2-015-F03.ttl': '', 'rdf/I2/I2-015/I2-015-F04.ttl': '', 'rdf/I2/I2-015/I2-015-F05.ttl': '', 'rdf/I2/I2-015/I2-015-P01.ttl': '', 'rdf/I2/I2-021/I2-021-F01.ttl': '', 'rdf/I2/I2-021/I2-021-F02.ttl': '', 'rdf/I2/I2-021/I2-021-F03.ttl': '', 'rdf/I2/I2-021/I2-021-P01.ttl': '', 'rdf/I2/I2-021/I2-021-P02.ttl': '', 'specifications/I2/I2-014.json': '', 'specifications/I2/I2-015.json': '', 'specifications/I2/I2-021.json': ''}


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def sha256(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def find_repo():
    candidates=[Path.cwd(),Path(__file__).resolve().parent]+list(Path(__file__).resolve().parents)
    seen=set()
    for c in candidates:
        c=c.resolve()
        if c in seen:
            continue
        seen.add(c)
        if (c/'MVP'/'BENCHMARK_VOCABULARY'/'FINAL_LOCK_R13'/'requirement_term_index.json').exists():
            return c
    raise RuntimeError('Could not locate NLTL_v2 repository root')


def verify_lock_files(root, lock, key='frozen_files'):
    mismatches=[]
    for rel,expected in lock.get(key,{}).items():
        p=root/rel
        if not p.exists() or sha256(p)!=expected:
            mismatches.append(rel)
    return mismatches


def verify_pilot(root, pilot_lock):
    mismatches=[]
    for rel,expected in pilot_lock['hashes'].items():
        p=root/rel
        if not p.exists() or sha256(p)!=expected:
            mismatches.append(rel)
    return mismatches


def migrate_batch(root, batch_letter, colliding_reqs):
    letter=batch_letter.lower()
    manifest_path=root/'manifests'/f'i2_batch_{letter}_manifest.jsonl'
    lock_path=root/'locks'/f'i2_batch_{letter}_fixture_lock.json'
    if not manifest_path.exists() or not lock_path.exists():
        raise SystemExit(f'Batch {batch_letter} manifest/lock not found. Run the already-issued Batch {batch_letter} first.')

    rows=[json.loads(x) for x in manifest_path.read_text().splitlines() if x.strip()]
    lock=json.loads(lock_path.read_text())

    # If this batch has not yet been migrated, require its original frozen lock to match
    # before touching anything. This prevents repairing an already-unexplained mutation.
    already=all(
        (r['requirement_id'] not in colliding_reqs) or r['case_id'].startswith(r['requirement_id']+f'-{batch_letter}-')
        for r in rows
    )
    if not already:
        mismatches=verify_lock_files(root,lock)
        if mismatches:
            raise SystemExit(
                f'Batch {batch_letter} does not match its pre-repair frozen lock; refusing automatic repair. Mismatches: '+', '.join(mismatches[:10])
            )

    reports=root/'reports'
    reports.mkdir(parents=True,exist_ok=True)
    pre_lock=reports/f'pre_integrity_repair_i2_batch_{letter}_fixture_lock.json'
    pre_manifest=reports/f'pre_integrity_repair_i2_batch_{letter}_manifest.jsonl'
    if not pre_lock.exists():
        shutil.copy2(lock_path,pre_lock)
    if not pre_manifest.exists():
        shutil.copy2(manifest_path,pre_manifest)

    if not already:
        for row in rows:
            req=row['requirement_id']
            if req not in colliding_reqs:
                continue
            old_case=row['case_id']
            prefix=req+'-'
            if not old_case.startswith(prefix):
                raise SystemExit(f'Unexpected Batch {batch_letter} case id: {old_case}')
            new_case=prefix+batch_letter+'-'+old_case[len(prefix):]
            old_path=root/row['rdf_path']
            new_path=old_path.with_name(new_case+'.ttl')
            text=old_path.read_text()
            # Synthetic benchmark resource IRIs include the case id. Rename only that
            # identifier so the batch artifact is self-consistent after path migration.
            text=text.replace(old_case,new_case)
            new_path.write_text(text)
            row['case_id']=new_case
            row['rdf_path']=str(new_path.relative_to(root))

        manifest_path.write_text(''.join(json.dumps(r)+'\n' for r in rows))

        # Move the Batch E/F specification to a batch-specific name before the old
        # shared path is restored to the exact Pilot-02 specification bytes.
        for req in colliding_reqs:
            old_spec=root/'specifications'/'I2'/f'{req}.json'
            new_spec=root/'specifications'/'I2'/f'{req}_batch_{letter}.json'
            spec=json.loads(old_spec.read_text())
            for tc in spec.get('test_cases',[]):
                old=tc['case_id']
                prefix=req+'-'
                if old.startswith(prefix) and not old.startswith(prefix+batch_letter+'-'):
                    tc['case_id']=prefix+batch_letter+'-'+old[len(prefix):]
            spec['integrity_repair_note']='Batch-specific filename/case-id migration to avoid collision with frozen Pilot 02; behavioral fixture content unchanged.'
            new_spec.write_text(json.dumps(spec,indent=2)+'\n')

    # Recompute the batch lock from the migrated manifest and batch-specific specs.
    rows=[json.loads(x) for x in manifest_path.read_text().splitlines() if x.strip()]
    frozen=[manifest_path]
    for req in lock['requirements']:
        if req in colliding_reqs:
            frozen.append(root/'specifications'/'I2'/f'{req}_batch_{letter}.json')
        else:
            frozen.append(root/'specifications'/'I2'/f'{req}.json')
    frozen += [root/r['rdf_path'] for r in rows]
    for p in frozen:
        if not p.exists():
            raise SystemExit(f'Expected Batch {batch_letter} frozen artifact missing: {p}')
    lock['frozen_files']={str(p.relative_to(root)):sha256(p) for p in frozen}
    lock['integrity_repair']='Resolved Batch E/F file-path collision with frozen Pilot 02; no benchmark logic was changed in response to generated-shape performance.'
    lock['pilot02_originals_restored']=True
    lock_path.write_text(json.dumps(lock,indent=2)+'\n')


def main():
    repo=find_repo()
    root=repo/'MVP'/'SHACL_GENERATION_PIPELINE'/'evaluation'/'BEHAVIORAL_RDF_R13'
    pilot_lock_path=root/'locks'/'pilot_02_fixture_lock.json'
    if not pilot_lock_path.exists():
        raise SystemExit('Pilot-02 fixture lock not found')
    pilot_lock=json.loads(pilot_lock_path.read_text())

    # Validate embedded source bytes against the immutable Pilot-02 lock before use.
    for rel,b64 in PILOT_ORIGINALS_B64.items():
        data=base64.b64decode(b64)
        expected=pilot_lock['hashes'].get(rel)
        if expected is None or sha256_bytes(data)!=expected:
            raise SystemExit(f'Embedded Pilot-02 recovery byte hash mismatch for {rel}')

    # Migrate currently frozen Batch E/F artifacts away from the shared Pilot paths.
    migrate_batch(root,'E',{'I2-014','I2-015'})
    migrate_batch(root,'F',{'I2-021'})

    # Restore exactly the original Pilot-02 bytes at the paths covered by its lock.
    for rel,b64 in PILOT_ORIGINALS_B64.items():
        p=root/rel
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_bytes(base64.b64decode(b64))

    pilot_mismatches=verify_pilot(root,pilot_lock)
    if pilot_mismatches:
        raise SystemExit('Pilot-02 lock is not restored: '+', '.join(pilot_mismatches[:10]))

    # Recompute E/F locks one final time now that shared Pilot paths are restored.
    # Migrated E/F locks no longer reference those shared paths.
    migrate_batch(root,'E',{'I2-014','I2-015'})
    migrate_batch(root,'F',{'I2-021'})

    for letter in ['e','f']:
        lock=json.loads((root/'locks'/f'i2_batch_{letter}_fixture_lock.json').read_text())
        mismatches=verify_lock_files(root,lock)
        if mismatches:
            raise SystemExit(f'Batch {letter.upper()} repaired lock mismatch: '+', '.join(mismatches[:10]))

    report=root/'reports'/'INTEGRITY_REPAIR_EF_PILOT02.md'
    report.write_text(
        '# Integrity repair: Batch E/F vs Pilot 02\n\n'
        'Date: 2026-09-10\n\n'
        'A file-namespace collision was detected after Batch E/F construction: Batch E reused the frozen Pilot-02 I2-014 and I2-015 RDF/specification paths, and Batch F reused the frozen Pilot-02 I2-021 paths. This was a benchmark infrastructure error, not a model-performance finding.\n\n'
        'Repair performed:\n\n'
        '1. Batch E collision artifacts were migrated to Batch-E-specific case IDs and specification filenames.\n'
        '2. Batch F collision artifacts were migrated to Batch-F-specific case IDs and specification filename.\n'
        '3. The exact original Pilot-02 bytes were restored and verified against the unchanged pilot_02_fixture_lock.json hashes.\n'
        '4. Batch E/F locks were recomputed over their migrated artifacts.\n'
        '5. No generated SHACL output was inspected and no source oracle or PASS/FAIL behavior was changed because of model performance.\n\n'
        'Original pre-repair Batch E/F manifests and locks are retained in this reports directory for auditability.\n'
    )

    print('Pilot 02 frozen hashes matched: YES')
    print('Repaired Batch E frozen hashes matched: YES')
    print('Repaired Batch F frozen hashes matched: YES')
    print('Migrated artifacts: 17 RDF fixtures + 3 specifications')
    print('Integrity repair status: PASS')
    print('')
    print('Running standalone Batch E/F validators...')
    for letter in ['e','f']:
        cmd=[sys.executable,str(root/'scripts'/f'validate_i2_batch_{letter}.py')]
        r=subprocess.run(cmd,cwd=root)
        if r.returncode!=0:
            raise SystemExit(f'Batch {letter.upper()} standalone validation failed after integrity repair')
    print('')
    print('All repair checks: PASS')


if __name__=='__main__':
    main()
